<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner Dashboard · EngineerLaunch</title><style>:root{--navy:#0d1b35;--blue:#2563eb;--muted:#718096;--line:#e4e9f2;--bg:#f5f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#10213e;font:14px Inter,system-ui}.top{height:70px;display:flex;align-items:center;padding:0 30px;background:var(--navy);color:#fff}.brand{font-size:22px;font-weight:850}.brand span{color:#60a5fa}.top nav{margin-left:auto;display:flex;gap:18px;align-items:center}.top a{color:#cbd5e1;text-decoration:none}.logout{padding:9px 14px;border:0;border-radius:8px;background:#2563eb;color:#fff}.page{width:min(1450px,calc(100% - 40px));margin:30px auto}.hero{display:flex;justify-content:space-between;align-items:end;margin-bottom:24px}.hero h1{font-size:31px;margin:0 0 7px}.muted{color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 8px 25px #10213e08}.metric{padding:20px}.metric span{color:var(--muted)}.metric b{display:block;font-size:29px;margin:10px 0}.grid{display:grid;grid-template-columns:1.25fr 1fr;gap:18px;margin-top:20px}.panel{padding:22px;overflow:auto}.panel h2{font-size:19px;margin:0 0 18px}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{color:var(--muted);font-size:11px;text-transform:uppercase}.bars{display:grid;gap:13px}.bar-row{display:grid;grid-template-columns:130px 1fr 45px;gap:10px;align-items:center}.track{height:10px;background:#edf2f7;border-radius:10px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#2563eb,#60a5fa);border-radius:10px}.danger{color:#b42318}.pill{display:inline-block;padding:5px 9px;border-radius:20px;background:#eef4ff;color:#2457bd;font-weight:700}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.hero{align-items:flex-start;flex-direction:column;gap:10px}.page{width:min(100% - 24px,1450px)}}</style></head><body><header class="top"><a class="brand" href="{{route('home')}}">Engineer<span>Launch</span></a><nav><a href="{{route('home')}}">Public portal</a><strong>{{auth()->user()->name}}</strong><form method="post" action="{{route('logout')}}">@csrf<button class="logout">Logout</button></form></nav></header><main class="page"><div class="hero"><div><h1>Platform Health Dashboard</h1><div class="muted">Live operational overview of employers, students, jobs and discovery activity.</div></div><div class="muted">Updated {{now()->format('d M Y, h:i A')}}</div></div><section class="metrics">@foreach(['companies'=>'Hiring Companies','hr'=>'HR Accounts','students'=>'Students','jobs'=>'HR Posted Jobs','applications'=>'Applications','visits'=>'Page Views','unique_visitors'=>'Unique Sessions','searches'=>'Job Searches','deleted_jobs'=>'Deleted Jobs'] as $key=>$label)<div class="card metric"><span>{{$label}}</span><b>{{number_format($metrics[$key])}}</b><small class="muted">Database total</small></div>@endforeach</section><div class="grid"><section class="card panel"><h2>What candidates search</h2><table><thead><tr><th>Keyword</th><th>Searches</th><th>Results shown</th></tr></thead><tbody>@forelse($searchTerms as $row)<tr><td><strong>{{$row->keyword}}</strong></td><td>{{$row->searches}}</td><td>{{$row->results}}</td></tr>@empty<tr><td colspan="3" class="muted">Search analytics will appear after candidates search.</td></tr>@endforelse</tbody></table></section><section class="card panel"><h2>Employer job status</h2><div class="bars">@php $max=max(1,$jobStatus->max('total')??1); @endphp @forelse($jobStatus as $row)<div class="bar-row"><span>{{ucwords($row->status)}}</span><div class="track"><div class="fill" style="width:{{round($row->total/$max*100)}}%"></div></div><strong>{{$row->total}}</strong></div>@empty<p class="muted">No employer jobs yet.</p>@endforelse</div></section><section class="card panel"><h2>Popular pages</h2><table><tr><th>Page</th><th>Views</th></tr>@foreach($popular as $row)<tr><td>{{$row->path}}</td><td>{{$row->visits}}</td></tr>@endforeach</table></section><section class="card panel"><h2>Recently deleted HR jobs</h2><table><tr><th>Job</th><th>Company / HR</th><th>Deleted</th></tr>@forelse($deleted as $row)<tr><td class="danger">{{$row->job_title}}</td><td>{{$row->company_name??$row->email??'Unknown'}}</td><td>{{$row->deleted_at}}</td></tr>@empty<tr><td colspan="3" class="muted">No HR jobs have been deleted.</td></tr>@endforelse</table></section><section class="card panel" style="grid-column:1/-1"><h2>Recent student and visitor activity</h2><table><tr><th>Time</th><th>User</th><th>Action</th><th>Page</th></tr>@foreach($recent as $row)<tr><td>{{$row->created_at}}</td><td>{{$row->email??'Guest visitor'}}</td><td><span class="pill">{{$row->action}}</span></td><td>{{$row->path}}</td></tr>@endforeach</table></section></div></main></body></html>
